import{_ as a,o,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Visión del proyecto","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/vision.md","filePath":"es/game-design/vision.md"}'),r={name:"es/game-design/vision.md"};function s(t,e,d,c,l,p){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="project-vision" tabindex="-1">Visión del proyecto <a class="header-anchor" href="#project-vision" aria-label="Enlace permanente a &quot;Visión del proyecto&quot;">​</a></h1><p><strong>Estado del diseño: Aceptado. Implementación: base UO existente con combate localizado experimental; los sistemas más amplios siguen siendo propuestas. Verificación: revisión del diseño, no un informe de disponibilidad actual.</strong></p><p>SyroUO Lab prioriza prototipos de juego rápidos y seguros con ModernUO, ClassicUO y recursos de UO obtenidos legalmente. Hay que validar la experiencia antes de sustituir infraestructura madura. Un futuro juego independiente depende de los resultados del Lab; no exige una reescritura ahora.</p><p>El combate debe seguir siendo accesible mediante ataques automáticos, mientras la interacción avanzada opcional recompensa tanto el criterio del jugador como la capacidad del personaje. Los mismos principios deben aplicarse a PvP y PvM cuando la anatomía lo permita. El equipo debe ser significativo, reemplazable y principalmente horizontal, en lugar de una escala de poder interminable.</p><p>Conceptos como la anatomía deben permanecer separados de las categorías de animación heredadas. Las abstracciones de bajo coste pueden permitir proveedores tradicionales y personalizados en paralelo; una independencia especulativa no debe retrasar el primer experimento jugable.</p><p><strong>Carencia:</strong> la validación ampliada de la experiencia de juego sigue incompleta. Aprobar un diseño no acredita funciones disponibles ni equilibrio validado.</p><p><a href="/Syrolands-Public/es/game-design/combat/overview.html">Combate</a> · Decisión del Lab · Hoja de ruta</p><h2 id="proposed-living-world-pillar" tabindex="-1">Pilar del mundo vivo — Propuesto <a class="header-anchor" href="#proposed-living-world-pillar" aria-label="Enlace permanente a &quot;Pilar del mundo vivo — Propuesto&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/living-world.html">Mundo vivo y materiales</a> propone cambios ambientales persistentes mediante reglas compartidas de materiales: silvicultura, fuego, terreno, magia y, más adelante, ecología. Su arquitectura de simulación dispersa y el prototipo candidato mantienen el estado Propuesto, con políticas de protección y regeneración sin resolver. Esto no añade ninguna decisión con estado Aceptado ni amplía el alcance de implementación de la fase actual de combate.</p><h2 id="proposed-combat-direction-—-batch-05" tabindex="-1">Dirección del combate — Propuesto — Batch 05 <a class="header-anchor" href="#proposed-combat-direction-—-batch-05" aria-label="Enlace permanente a &quot;Dirección del combate — Propuesto — Batch 05&quot;">​</a></h2><p>La base automática anterior con estado Aceptado documenta el experimento existente. La <a href="/Syrolands-Public/es/game-design/combat/legacy-and-modern.html">propuesta Legacy/Modern</a>, más reciente, convierte la cadencia iniciada por el jugador de Modern en la dirección experimental preferida, conservando la cadencia automática de Legacy como opción compatible de respaldo, accesibilidad y nostalgia. Esta preferencia tiene estado Propuesto; no supone aprobar ni entregar un sistema sustituto. Las reglas compartidas de recursos y la viabilidad de Legacy siguen siendo requisitos.</p><p>La <a href="/Syrolands-Public/es/guide/introduction.html">introducción para jugadores</a> presenta los pilares de mundo, combate, conocimiento, artesanía, magia y múltiples metas a largo plazo mediante un recorrido breve; las propuestas conservan su estado existente.</p>',12)])])}const g=a(r,[["render",s]]);export{u as __pageData,g as default};
